#include "AsyncActions/HorizonAsync_SharedObjects.h"
#include "HorizonBlueprintLibrary.h"
#include "HorizonSubsystem.h"
#include "Managers/HorizonSharedObjectsManager.h"
void UHorizonAsync_SharedBase::Freeze(const UObject* W){World=W;auto* S=UHorizonBlueprintLibrary::GetHorizonSubsystem(W);OriginalSubsystem=S;if(S&&S->Auth){User=S->Auth->GetCurrentUser().UserId;Context=S->GetHttpClient()->GetRequestContextEpoch();}RegisterWithGameInstance(W);}
UHorizonSubsystem* UHorizonAsync_SharedBase::Resolve(FString& Code){auto* S=UHorizonBlueprintLibrary::GetHorizonSubsystem(World.Get());if(!S||!S->SharedObjects){Code=TEXT("SDK_NOT_CONNECTED");return nullptr;}if(S!=OriginalSubsystem.Get()||S->GetHttpClient()->GetRequestContextEpoch()!=Context){Code=TEXT("STALE_RESPONSE");return nullptr;}return S;}
UHorizonAsync_SharedCollections* UHorizonAsync_SharedCollections::GetCollections(const UObject* W,const FString& AfterKey,int32 Limit,int64 CatalogRevision){auto* A=NewObject<UHorizonAsync_SharedCollections>();A->Freeze(W);A->After=AfterKey;A->Limit=Limit;A->Revision=CatalogRevision;return A;}
void UHorizonAsync_SharedCollections::Activate(){if(Activated)return;Activated=true;FString Code;auto* S=Resolve(Code);if(!S){Complete(false,{},Code,Code);return;}S->SharedObjects->GetCollections(User,FOnSharedCollectionsComplete::CreateUObject(this,&UHorizonAsync_SharedCollections::Complete),After,Limit,Revision);}
void UHorizonAsync_SharedCollections::Complete(bool Ok,const FHorizonSharedCollectionPage& R,const FString& Code,const FString& Message){OnComplete.Broadcast(Ok,R,Code,Message);SetReadyToDestroy();}
UHorizonAsync_SharedUsage* UHorizonAsync_SharedUsage::GetUsage(const UObject* W,const FString& Collection){auto* A=NewObject<UHorizonAsync_SharedUsage>();A->Freeze(W);A->Collection=Collection;return A;}
void UHorizonAsync_SharedUsage::Activate(){if(Activated)return;Activated=true;FString Code;auto* S=Resolve(Code);if(!S){Complete(false,{},Code,Code);return;}S->SharedObjects->GetUsage(User,Collection,FOnSharedUsageComplete::CreateUObject(this,&UHorizonAsync_SharedUsage::Complete));}
void UHorizonAsync_SharedUsage::Complete(bool Ok,const FHorizonSharedUsage& R,const FString& Code,const FString& Message){OnComplete.Broadcast(Ok,R,Code,Message);SetReadyToDestroy();}
UHorizonAsync_SharedObject* UHorizonAsync_SharedObject::GetObject(const UObject* W,const FString& Collection,const FString& ObjectId){auto* A=NewObject<UHorizonAsync_SharedObject>();A->Freeze(W);A->Collection=Collection;A->Id=ObjectId;return A;}
void UHorizonAsync_SharedObject::Activate(){if(Activated)return;Activated=true;FString Code;auto* S=Resolve(Code);if(!S){Complete(false,{},Code,Code);return;}S->SharedObjects->GetObject(User,Collection,Id,FOnSharedObjectComplete::CreateUObject(this,&UHorizonAsync_SharedObject::Complete));}
void UHorizonAsync_SharedObject::Complete(bool Ok,const FHorizonSharedObjectRead& R,const FString& Code,const FString& Message){OnComplete.Broadcast(Ok,R,Code,Message);SetReadyToDestroy();}
UHorizonAsync_SharedQuery* UHorizonAsync_SharedQuery::QueryObjects(const UObject* W,const FString& Collection,const FHorizonSharedQuery& Query){auto* A=NewObject<UHorizonAsync_SharedQuery>();A->Freeze(W);A->Collection=Collection;A->Query=Query;return A;}
void UHorizonAsync_SharedQuery::Activate(){if(Activated)return;Activated=true;FString Code;auto* S=Resolve(Code);if(!S){Complete(false,{},Code,Code);return;}S->SharedObjects->QueryObjects(User,Collection,Query,FOnSharedQueryComplete::CreateUObject(this,&UHorizonAsync_SharedQuery::Complete));}
void UHorizonAsync_SharedQuery::Complete(bool Ok,const FHorizonSharedQueryResult& R,const FString& Code,const FString& Message){OnComplete.Broadcast(Ok,R,Code,Message);SetReadyToDestroy();}
UHorizonAsync_SharedWrite* UHorizonAsync_SharedWrite::CreateObject(const UObject* W,const FString& Collection,int64 ExpectedUsageRevision,const FHorizonSharedObjectInput& Input,const FString& GroupId){auto* A=NewObject<UHorizonAsync_SharedWrite>();A->Freeze(W);A->Collection=Collection;A->Revision=ExpectedUsageRevision;A->Input=Input;A->Group=GroupId;A->Create=true;return A;}
UHorizonAsync_SharedWrite* UHorizonAsync_SharedWrite::UpdateObject(const UObject* W,const FString& Collection,const FString& ObjectId,int64 ExpectedObjectRevision,const FHorizonSharedObjectInput& Input){auto* A=NewObject<UHorizonAsync_SharedWrite>();A->Freeze(W);A->Collection=Collection;A->Id=ObjectId;A->Revision=ExpectedObjectRevision;A->Input=Input;A->Create=false;return A;}
void UHorizonAsync_SharedWrite::Activate(){if(Activated)return;Activated=true;FString Code;auto* S=Resolve(Code);if(!S){Complete(false,{},Code,Code);return;}const auto D=FOnSharedWriteComplete::CreateUObject(this,&UHorizonAsync_SharedWrite::Complete);if(Create)S->SharedObjects->CreateObject(User,Collection,Revision,Input,D,Group);else S->SharedObjects->UpdateObject(User,Collection,Id,Revision,Input,D);}
void UHorizonAsync_SharedWrite::Complete(bool Ok,const FHorizonSharedWriteResult& R,const FString& Code,const FString& Message){OnComplete.Broadcast(Ok,R,Code,Message);SetReadyToDestroy();}
UHorizonAsync_SharedDelete* UHorizonAsync_SharedDelete::DeleteObject(const UObject* W,const FString& Collection,const FString& ObjectId,int64 ExpectedObjectRevision){auto* A=NewObject<UHorizonAsync_SharedDelete>();A->Freeze(W);A->Collection=Collection;A->Id=ObjectId;A->Revision=ExpectedObjectRevision;return A;}
void UHorizonAsync_SharedDelete::Activate(){if(Activated)return;Activated=true;FString Code;auto* S=Resolve(Code);if(!S){Complete(false,{},Code,Code);return;}S->SharedObjects->DeleteObject(User,Collection,Id,Revision,FOnSharedDeleteComplete::CreateUObject(this,&UHorizonAsync_SharedDelete::Complete));}
void UHorizonAsync_SharedDelete::Complete(bool Ok,const FHorizonSharedDeleteResult& R,const FString& Code,const FString& Message){OnComplete.Broadcast(Ok,R,Code,Message);SetReadyToDestroy();}
